{"script":"cat << 'EOF' > process.py
import os

files = set()
errors = []

with open('temp_var_inventory/raw_listing.txt', 'r') as f:
    for line in f:
        parts = line.strip().split(' ', 1)
        if len(parts) == 2:
            ftype, path = parts
            try:
                real_path = os.path.realpath(path)

                if not os.path.exists(real_path):
                    if ftype == 'l':
                        errors.append(f"Unresolved link: {path}")
                    continue

                if os.path.isfile(real_path):
                    files.add(real_path)
            except Exception as e:
                errors.append(f"Error processing {path}: {e}")

with open('temp_var_inventory/errors.log', 'a') as f:
    for err in errors:
        f.write(err + '\n')

with open('temp_var_inventory/file_list.txt', 'w') as f:
    for file in sorted(files):
        f.write(file + '\n')

print(len(files))
EOF
python3 process.py
